function newWizard(){flushInputs();const box=E('div',{},[E('div',{class:'welcome-tag',text:'From first project to first opportunity'}),E('p',{class:'help',text:'Start with an empty canvas or a small, editable foundation. Every starter uses the same components and grid controls.'})]),choices=E('div',{class:'choice-grid'});for(const [name,desc]of [['Blank canvas','Add your own sections and build from the ground up.'],['Gameplay Programmer','Profile, project cards, about, and contact.'],['Game Artist','Visual project cards with category filters.'],['Technical Artist','A quiet canvas for tools, shaders, and breakdowns.'],['Game Animator','A home for your reel and animation studies.']]){choices.append(E('button',{onclick:()=>{const start=()=>{history.push(snapshot());future=[];scope='desktop';$('device').value='1280';setDocument(name==='Blank canvas'?M.fresh():M.starter(name==='Gameplay Programmer'?'Game Programmer':name));assets=new Map();folders=new Set();ensureArchive();data.sections.forEach(protectedFolders);selection={};previewPage='';scrollPosition=0;dirty=true;closeModal();render();queueSave();};if(dirty||data.sections.length)confirmAction('Start a new portfolio?','Export or save your current work first. The previous portfolio is available through Undo during this session.',start);else start();}},[E('strong',{text:name}),E('small',{text:desc})]));}box.append(choices);modal('Make space for your work.',box);}
